/** Compute Entrypoint Contract
  *
  * guarantee CASE_06_regulator_health_decision
  * @param In_regulator_mode_state pre-state state variable
  * @param regulator_mode_state post-state state variable
  * @param api_diagnostic_facts incoming data port
  * @param api_interface_facts incoming data port
  */
pub fn compute_spec_CASE_06_regulator_health_decision_guarantee(
  In_regulator_mode_state: Isolette_Thermostat_Rust::ThermostatMode,
  regulator_mode_state: Isolette_Thermostat_Rust::ThermostatMode,
  api_diagnostic_facts: Isolette_Thermostat_Rust::RegulatorDiagnosticFacts,
  api_interface_facts: Isolette_Thermostat_Rust::RegulatorInterfaceFacts) -> bool
{
  (implies!(
    !(api_diagnostic_facts.power_epoch_changed) & !(api_interface_facts.interface_failure) &
      !(api_diagnostic_facts.internal_failure_latched) &
      api_interface_facts.current_valid &
      (In_regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::INIT),
    (regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::NORMAL))) &
    (implies!(
      !(api_diagnostic_facts.power_epoch_changed) & !(api_interface_facts.interface_failure) &
        !(api_diagnostic_facts.internal_failure_latched) &
        api_interface_facts.current_valid &
        (In_regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::NORMAL),
      (regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::NORMAL)))
}

/** Compute Entrypoint Contract
  *
  * guarantee CASE_07_regulator_mode_transition
  * @param In_regulator_mode_state pre-state state variable
  * @param regulator_mode_state post-state state variable
  * @param api_diagnostic_facts incoming data port
  * @param api_interface_facts incoming data port
  * @param api_mode_for_heat outgoing data port
  * @param api_mode_for_interface outgoing data port
  */
pub fn compute_spec_CASE_07_regulator_mode_transition_guarantee(
  In_regulator_mode_state: Isolette_Thermostat_Rust::ThermostatMode,
  regulator_mode_state: Isolette_Thermostat_Rust::ThermostatMode,
  api_diagnostic_facts: Isolette_Thermostat_Rust::RegulatorDiagnosticFacts,
  api_interface_facts: Isolette_Thermostat_Rust::RegulatorInterfaceFacts,
  api_mode_for_heat: Isolette_Thermostat_Rust::ThermostatMode,
  api_mode_for_interface: Isolette_Thermostat_Rust::ThermostatMode) -> bool
{
  (implies!(
    api_diagnostic_facts.power_epoch_changed,
    (regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::INIT))) &
    (implies!(
      !(api_diagnostic_facts.power_epoch_changed) &
        (In_regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::FAILED),
      (regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::FAILED))) &
    (implies!(
      !(api_diagnostic_facts.power_epoch_changed) &
        (In_regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::INIT) &
        (api_interface_facts.interface_failure | api_diagnostic_facts.internal_failure_latched |
          !(api_interface_facts.current_valid)) &
        api_diagnostic_facts.init_timeout_expired,
      (regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::FAILED))) &
    (implies!(
      !(api_diagnostic_facts.power_epoch_changed) &
        (In_regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::INIT) &
        (api_interface_facts.interface_failure | api_diagnostic_facts.internal_failure_latched |
          !(api_interface_facts.current_valid)) &
        !(api_diagnostic_facts.init_timeout_expired),
      (regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::INIT))) &
    (implies!(
      !(api_diagnostic_facts.power_epoch_changed) &
        (In_regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::NORMAL) &
        (api_interface_facts.interface_failure | api_diagnostic_facts.internal_failure_latched |
          !(api_interface_facts.current_valid)),
      (regulator_mode_state == Isolette_Thermostat_Rust::ThermostatMode::FAILED))) &
    (api_mode_for_interface == regulator_mode_state) &
    (api_mode_for_heat == regulator_mode_state)
}

